"use client";
import Breadcrumb from "@/components/header/breadcrumb";
import { useState, useEffect } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCheck, faXmark } from "@fortawesome/free-solid-svg-icons";
import { apiClient } from "@/lib/apiClient";

export default function Page({ activationCode }: { activationCode: string }) {
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      // apiv3 B2B: POST /b2b/representative/activation (app-token).
      return apiClient("/b2b/representative/activation", {
        method: "POST",
        body: { params: { ssr: true, activation_code: activationCode } },
      });
    };

    fetchData()
      .then((res) => {
        setLoading(false);
        if (res.success) {
          setStatus("activated");
        } else {
          setStatus("notactivated");
        }
      })
      .catch(() => {
        setLoading(false);
        setStatus("notactivated");
      });
  }, []);

  return (
    <main>
      <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4 tw-my-8">
        <Breadcrumb
          items={[
            {
              pageTitle: "Representative Activation",
              pageUrl: "",
            },
          ]}
        />
        <h1 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c]">
          Representative Activation
        </h1>
        <div className="tw-mx-auto tw-mt-6 tw-max-w-lg tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_14px_34px_rgba(20,16,28,0.06)]">
          <div className="tw-p-8 tw-text-center md:tw-p-10">
            {loading && (
              <>
                <span className="tw-mx-auto tw-mb-5 tw-inline-block tw-h-16 tw-w-16 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#ece9f1] tw-border-t-[#854ec9]" />
                <p className="tw-m-0 tw-text-base tw-font-semibold tw-text-[#14101c]">
                  Mail activating...
                </p>
                <p className="tw-mt-1 tw-mb-0 tw-text-sm tw-text-[#5d556c]">
                  Please wait for activating. It will some seconds.
                </p>
              </>
            )}
            {!loading && status === "activated" && (
              <>
                <div className="tw-mx-auto tw-mb-4 tw-flex tw-h-16 tw-w-16 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#e8f7ee] tw-text-[#1a9c54]">
                  <FontAwesomeIcon icon={faCheck} className="tw-text-2xl" />
                </div>
                <h2 className="tw-font-display tw-m-0 tw-text-xl tw-font-bold tw-text-[#1a9c54]">
                  Mail activating success
                </h2>
                <p className="tw-mt-2 tw-mb-0 tw-text-sm tw-text-[#5d556c]">
                  Please wait for confirm your registration request.
                </p>
              </>
            )}
            {!loading && status === "notactivated" && (
              <>
                <div className="tw-mx-auto tw-mb-4 tw-flex tw-h-16 tw-w-16 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#fdecec] tw-text-[#b3261e]">
                  <FontAwesomeIcon icon={faXmark} className="tw-text-2xl" />
                </div>
                <h2 className="tw-font-display tw-m-0 tw-text-xl tw-font-bold tw-text-[#b3261e]">
                  Mail activating failed
                </h2>
                <p className="tw-mt-2 tw-mb-0 tw-text-sm tw-text-[#5d556c]">
                  Please contact with TravelShop Booking Support Team.
                </p>
              </>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
